import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, throwError } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { ApiService } from './api.service';
import { LoginRequest, LoginResponse, User } from '../models/user.model'; // Ensure LoginResponse is correctly defined
import { environment } from '../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private currentUserSubject: BehaviorSubject<User | null>;
  public currentUser$: Observable<User | null>;
  public isLoggedIn$: Observable<boolean>;

  constructor(private apiService: ApiService) {
    const storedUser = localStorage.getItem(`${environment.storagePrefix}user`);
    this.currentUserSubject = new BehaviorSubject<User | null>(
      storedUser ? JSON.parse(storedUser) : null
    );
    this.currentUser$ = this.currentUserSubject.asObservable();
    this.isLoggedIn$ = this.currentUser$.pipe(map(user => !!user));
  }

  public get currentUserValue(): User | null {
    return this.currentUserSubject.value;
  }

  public get isLoggedIn(): boolean {
    return !!this.currentUserValue;
  }

  login(email: string, password: string): Observable<LoginResponse> {
    const loginData: LoginRequest = { email, password };
    return this.apiService.post<LoginResponse>('api/v1/auth/login', loginData).pipe(
      tap(response => {
        // Assuming the actual user data is nested under 'data'
        const userData = response.data;
        const user = new User(
          0, // Assuming ID is not directly in login response, or set a default/fetch later
          userData.email,
          userData.username,
          userData.roles.map(role => role.authority) // Extract role strings
        );
        localStorage.setItem(`${environment.storagePrefix}user`, JSON.stringify(user));
        localStorage.setItem(`${environment.storagePrefix}token`, userData.token); // Store the token
        this.currentUserSubject.next(user);
      }),
      catchError(error => {
        console.error('Login error', error);
        // It's often better to let the component handle UI updates for errors
        return throwError(() => error);
      })
    );
  }

  logout(): void { // Simplified logout, assuming no API call or it's handled elsewhere
    localStorage.removeItem(`${environment.storagePrefix}user`);
    localStorage.removeItem(`${environment.storagePrefix}token`);
    this.currentUserSubject.next(null);
    // Optionally, navigate to login page or reload the app
    // this.router.navigate(['/login']);
  }

  // Add other methods like register, getUserProfile, updateProfile, changePassword as needed,
  // ensuring they correctly interact with the API and update user state.

  // Example: getToken to be used by an interceptor
  public getToken(): string | null {
    return localStorage.getItem(`${environment.storagePrefix}token`);
  }
}
